#' Regression Discontinuity
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param treatment .
#' @param covs .
#' @param cluster .
#' @param cutVar .
#' @param cutoff .
#' @param kink .
#' @param p .
#' @param q .
#' @param bwselect .
#' @param hManual .
#' @param bManual .
#' @param kernel .
#' @param vce .
#' @param nnmatch .
#' @param level .
#' @param donut Observations closer than this to the cutoff are dropped.
#' @param plot .
#' @param plotBins .
#' @param plotOrder .
#' @param plotWindow .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$estimates} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$firstStage} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rdPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
rd <- function(
    data,
    outcome,
    running,
    treatment,
    covs,
    cluster,
    cutVar,
    cutoff = 0,
    kink = FALSE,
    p = 1,
    q = 0,
    bwselect = "mserd",
    hManual = 0,
    bManual = 0,
    kernel = "triangular",
    vce = "nn",
    nnmatch = 3,
    level = 95,
    donut = 0,
    plot = TRUE,
    plotBins = "esmv",
    plotOrder = 4,
    plotWindow = FALSE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rd requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(cutVar)) cutVar <- jmvcore::resolveQuo(jmvcore::enquo(cutVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(cutVar), cutVar, NULL))


    options <- rdOptions$new(
        outcome = outcome,
        running = running,
        treatment = treatment,
        covs = covs,
        cluster = cluster,
        cutVar = cutVar,
        cutoff = cutoff,
        kink = kink,
        p = p,
        q = q,
        bwselect = bwselect,
        hManual = hManual,
        bManual = bManual,
        kernel = kernel,
        vce = vce,
        nnmatch = nnmatch,
        level = level,
        donut = donut,
        plot = plot,
        plotBins = plotBins,
        plotOrder = plotOrder,
        plotWindow = plotWindow,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

